/// Takes back the last move, once.
fn undo(scene: &mut GameScene<'_>) {
    let (dx, dz) = (scene.counter_or("last_dx", 0), scene.counter_or("last_dz", 0));
    if (dx, dz) == (0, 0) {
        return;
    }
    let player = scene.object("Player").position();
    let (x, z) = cell(player);
    if scene.counter_or("last_push", 0) == 1 {
        if let Some(pushed) = on_cell(scene, "box", (x + dx, z + dz)) {
            let y = scene.object(&pushed).position()[1];
            scene.object(&pushed).set_position([x as f32, y, z as f32]);
        }
    }
    scene.object("Player").set_position([
        (x - dx) as f32,
        player[1],
        (z - dz) as f32,
    ]);
    scene.set_counter("last_dx", 0);
    scene.set_counter("last_dz", 0);
    count_boxes(scene);
}

fn count_boxes(scene: &mut GameScene<'_>) {
    let goals: Vec<_> = scene
        .in_class("goal")
        .into_iter()
        .map(|goal| cell(scene.object(&goal).position()))
        .collect();
    let solved = scene
        .in_class("box")
        .into_iter()
        .filter(|name| goals.contains(&cell(scene.object(name).position())))
        .count();
    scene.set_counter("boxes", solved as i32);
}
